cat > src/util/audit.ts <<'BENCHEOF'
/**
 * Append-only audit trail. Entries are flushed by the nightly reporting job.
 */
export interface AuditEntry {
  event: string;
  detail: Record<string, unknown>;
}

const entries: AuditEntry[] = [];

export function audit(event: string, detail: Record<string, unknown> = {}): void {
  entries.push({ event, detail });
}

export function auditTrail(): AuditEntry[] {
  return entries;
}

export function resetAudit(): void {
  entries.length = 0;
}
BENCHEOF

