cat > tests/audit.test.js <<'BENCHEOF'
import { test } from "node:test";
import assert from "node:assert";
import { auditTrail, resetAudit } from "../src/util/audit.ts";
import { auditHoldPlaced } from "../src/inventory/reserve.ts";
import { auditStockAdjusted } from "../src/inventory/stock.ts";
import { auditTokenSigned } from "../src/auth/token.ts";

test("audit entries record the event and its detail", () => {
  resetAudit();
  auditHoldPlaced("sku-1", 2);
  auditStockAdjusted("sku-1", -2);
  auditTokenSigned("usr_1");
  assert.deepEqual(auditTrail(), [
    { event: "hold.placed", detail: { sku: "sku-1", qty: 2 } },
    { event: "stock.adjusted", detail: { sku: "sku-1", delta: -2 } },
    { event: "token.signed", detail: { subject: "usr_1" } },
  ]);
});
BENCHEOF
